    fs.writeFileSync(file, `<!doctype html><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=${url}"><title>Deliberation dashboard</title><a href="${url}">Open the dashboard</a>\n`, { mode: 0o600 });
